<?php
namespace Tests\Feature;
use App\Models\Customer; use App\Models\Event; use App\Models\EventMealOption; use App\Models\EventPackage; use App\Models\InvitationParty; use App\Models\Rsvp; use App\Models\User; use Illuminate\Foundation\Testing\RefreshDatabase; use Inertia\Testing\AssertableInertia as Assert; use Tests\TestCase;
class RsvpTest extends TestCase { use RefreshDatabase;
 public function test_parties_receive_unique_opaque_tokens_and_pending_rsvps(): void { $event=$this->event(); $one=InvitationParty::create(['event_id'=>$event->id,'name'=>'One','maximum_party_size'=>1]); $two=InvitationParty::create(['event_id'=>$event->id,'name'=>'Two','maximum_party_size'=>1]); $this->assertNotSame($one->rsvp_token,$two->rsvp_token); $this->assertSame(64,strlen($one->rsvp_token)); $this->assertNotSame((string)$one->id,$one->rsvp_token); $this->assertSame('pending',$one->rsvp->status); $this->get(route('public.rsvp.show','bad-token'))->assertNotFound(); }
 public function test_token_regeneration_invalidates_old_token(): void { $admin=User::factory()->create(['role'=>'admin']); $event=$this->event(); $party=InvitationParty::create(['event_id'=>$event->id,'name'=>'Party','maximum_party_size'=>1]); $old=$party->rsvp_token; $this->actingAs($admin)->patch(route('events.guests.rsvp-token',[$event,$party]))->assertRedirect(); $party->refresh(); $this->assertNotSame($old,$party->rsvp_token); $this->get(route('public.rsvp.show',$old))->assertNotFound(); $this->get(route('public.rsvp.show',$party->rsvp_token))->assertOk(); }
 public function test_party_can_submit_attending_and_update_before_deadline_with_meals_and_notes(): void { $event=$this->event(); $party=InvitationParty::create(['event_id'=>$event->id,'name'=>'Family','maximum_party_size'=>3]); $member=$party->members()->create(['first_name'=>'John','member_type'=>'adult']); $meal=$event->mealOptions()->create(['name'=>'Chicken','is_active'=>true]); $payload=['status'=>'attending','guest_message'=>'Looking forward to it','members'=>[['id'=>$member->id,'is_attending'=>true,'event_meal_option_id'=>$meal->id,'dietary_note'=>'Nut allergy']],'additional_guests'=>[['first_name'=>'Emma','last_name'=>'Smith','member_type'=>'child','event_meal_option_id'=>$meal->id,'dietary_note'=>'No dairy']]]; $this->post(route('public.rsvp.submit',$party->rsvp_token),$payload)->assertRedirect(); $rsvp=$party->fresh()->rsvp; $this->assertSame('attending',$rsvp->status); $this->assertSame('Looking forward to it',$rsvp->guest_message); $this->assertCount(2,$rsvp->personResponses); $this->assertDatabaseHas('rsvp_person_responses',['rsvp_id'=>$rsvp->id,'dietary_note'=>'Nut allergy','is_original_party_member'=>true]); $payload['guest_message']='Updated message'; $payload['members'][0]['is_attending']=false; $payload['additional_guests']=[]; $this->post(route('public.rsvp.submit',$party->rsvp_token),$payload)->assertRedirect(); $this->assertSame(1,Rsvp::count()); $this->assertSame('Updated message',$rsvp->fresh()->guest_message); }
 public function test_party_can_decline_and_deadline_blocks_changes(): void { $event=$this->event(); $party=InvitationParty::create(['event_id'=>$event->id,'name'=>'Party','maximum_party_size'=>1]); $this->post(route('public.rsvp.submit',$party->rsvp_token),['status'=>'not_attending','guest_message'=>'Sorry'])->assertRedirect(); $this->assertSame('not_attending',$party->fresh()->rsvp->status); $event->update(['rsvp_deadline'=>now()->subDay()->toDateString()]); $this->post(route('public.rsvp.submit',$party->rsvp_token),['status'=>'attending'])->assertSessionHasErrors('status'); }
 public function test_public_page_shares_submitted_rsvp_summary_data_and_safe_formatted_event_context(): void { $event=$this->event(); $event->update(['main_date'=>'2026-08-22','start_time'=>'18:30','end_time'=>'23:00','venue'=>'Cedar Hall','address'=>'1 Cedar Street','location_url'=>'https://maps.example.test/cedar','rsvp_deadline'=>'2026-08-20']); $party=InvitationParty::create(['event_id'=>$event->id,'name'=>'Party','maximum_party_size'=>1]); $meal=$event->mealOptions()->create(['name'=>'Fish','is_active'=>true]); $rsvp=$party->rsvp; $rsvp->update(['status'=>'attending','guest_message'=>'See you soon','submitted_at'=>'2026-08-11 10:32:40','last_updated_at'=>'2026-08-11 10:32:40']); $rsvp->personResponses()->create(['first_name'=>'Nadia','member_type'=>'adult','is_attending'=>true,'event_meal_option_id'=>$meal->id,'dietary_note'=>'No dairy']); $this->get(route('public.rsvp.show',$party->rsvp_token))->assertInertia(fn (Assert $page) => $page->component('PublicRsvp')->where('rsvp.status','attending')->where('rsvp.guest_message','See you soon')->where('rsvp.submitted_at','August 11, 2026 at 10:32 AM')->where('rsvp.last_updated_at','August 11, 2026 at 10:32 AM')->where('rsvp.person_responses.0.meal_option.name','Fish')->missing('rsvp.id')->missing('rsvp.created_at')->where('party.name','Party')->where('party.event.event_type','Wedding')->where('party.event.main_date','Saturday, August 22, 2026')->where('party.event.start_time','6:30 PM')->where('party.event.end_time','11:00 PM')->where('party.event.venue','Cedar Hall')->where('party.event.address','1 Cedar Street')->where('party.event.location_url','https://maps.example.test/cedar')->where('party.event.rsvp_deadline','August 20, 2026 at 11:59 PM (UTC)')->missing('party.event.customer_id')->missing('party.event.id')->where('closed',false)); $event->update(['rsvp_deadline'=>now()->subDay()->toDateString()]); $this->get(route('public.rsvp.show',$party->rsvp_token))->assertInertia(fn (Assert $page) => $page->component('PublicRsvp')->where('rsvp.status','attending')->where('closed',true)); }
 public function test_public_submission_cannot_exceed_capacity_or_use_wrong_or_inactive_meal(): void { $event=$this->event(); $party=InvitationParty::create(['event_id'=>$event->id,'name'=>'Party','maximum_party_size'=>1]); $member=$party->members()->create(['first_name'=>'John','member_type'=>'adult']); $wrong=$this->event()->mealOptions()->create(['name'=>'Wrong','is_active'=>true]); $inactive=$event->mealOptions()->create(['name'=>'Inactive','is_active'=>false]); $base=['status'=>'attending','members'=>[['id'=>$member->id,'is_attending'=>true,'event_meal_option_id'=>$wrong->id]],'additional_guests'=>[]]; $this->post(route('public.rsvp.submit',$party->rsvp_token),$base)->assertSessionHasErrors('members'); $base['members'][0]['event_meal_option_id']=$inactive->id; $this->post(route('public.rsvp.submit',$party->rsvp_token),$base)->assertSessionHasErrors('members'); $base['members'][0]['event_meal_option_id']=null; $base['additional_guests']=[['first_name'=>'Extra','member_type'=>'adult']]; $this->post(route('public.rsvp.submit',$party->rsvp_token),$base)->assertSessionHasErrors('additional_guests'); }
 public function test_protected_rsvp_pages_format_submission_dates_without_duplicate_initial_update(): void { $admin=User::factory()->create(['role'=>'admin']); $event=$this->event(); $party=InvitationParty::create(['event_id'=>$event->id,'name'=>'Party','maximum_party_size'=>1]); $rsvp=$party->rsvp; $rsvp->update(['status'=>'attending','submitted_at'=>'2026-08-11 10:08:42','last_updated_at'=>'2026-08-11 10:08:42']); $this->actingAs($admin)->get(route('events.rsvps.index',$event))->assertInertia(fn (Assert $page) => $page->component('Events/Rsvps/Index')->where('parties.0.rsvp.submitted_at','August 11, 2026 at 10:08 AM')->where('parties.0.rsvp.last_updated_at',null)); $rsvp->update(['last_updated_at'=>'2026-08-11 10:55:00']); $this->actingAs($admin)->get(route('events.rsvps.show',[$event,$party]))->assertInertia(fn (Assert $page) => $page->component('Events/Rsvps/Show')->where('party.rsvp.submitted_at','August 11, 2026 at 10:08 AM')->where('party.rsvp.last_updated_at','August 11, 2026 at 10:55 AM')); }
 public function test_event_rsvp_summary_uses_actual_attending_people_and_permissions_are_enforced(): void { $admin=User::factory()->create(['role'=>'admin']); $customer=Customer::create(['name'=>'Customer']); $owner=User::factory()->create(['role'=>'customer','customer_id'=>$customer->id]); $support=User::factory()->create(['role'=>'support']); $event=$this->event($customer); $event->members()->attach($owner,['role'=>'editor']); $party=InvitationParty::create(['event_id'=>$event->id,'name'=>'Party','maximum_party_size'=>4]); $rsvp=$party->rsvp; $rsvp->update(['status'=>'attending','submitted_at'=>now(),'last_updated_at'=>now()]); $rsvp->personResponses()->createMany([['first_name'=>'Adult','member_type'=>'adult','is_attending'=>true],['first_name'=>'Child','member_type'=>'child','is_attending'=>true],['first_name'=>'Declined','member_type'=>'adult','is_attending'=>false]]); $this->actingAs($admin)->get(route('events.rsvps.index',$event))->assertOk()->assertSee('attending_people'); $this->actingAs($owner)->post(route('events.meals.store',$event),['name'=>'Fish'])->assertRedirect(); $this->actingAs($support)->get(route('events.rsvps.index',$event))->assertOk(); $this->actingAs($support)->post(route('events.meals.store',$event),['name'=>'No access'])->assertForbidden(); $other=User::factory()->create(['role'=>'customer','customer_id'=>Customer::create(['name'=>'Other'])->id]); $this->actingAs($other)->get(route('events.rsvps.index',$event))->assertForbidden(); }
 private function event(?Customer $customer=null): Event { $customer??=Customer::create(['name'=>'Customer '.uniqid()]); $package=EventPackage::create(['name'=>'Package '.uniqid(),'minimum_guests'=>1,'maximum_guests'=>50,'price'=>25,'is_active'=>true]); return Event::create(['customer_id'=>$customer->id,'event_package_id'=>$package->id,'title'=>'Event '.uniqid(),'event_type'=>'wedding','host_name'=>'Host','status'=>'draft','rsvp_deadline'=>now()->addWeek()->toDateString()]); }
}
